<?php
 define ('E_FATAL_ERROR', -9999); $jsonRpcExceptionNoDebug = false; class JsonRpcClientException extends ErrorException { public $jsonRpcError; public function __construct($jsonRpcError) { $this->jsonRpcError = $jsonRpcError; parent::__construct(); } } set_error_handler(function ($err_severity, $err_msg, $err_file, $err_line) { if (0 === error_reporting()) { return false; } throw new ErrorException($err_msg, 0, $err_severity, $err_file, $err_line); }); function decorateException (Throwable $e): Throwable { if (is_a($e, 'PDOException')) { $c = $e->getCode(); $msg = $e->getMessage(); if (isset($e->isASA)) { if (preg_match('/.+(Index).+(for table).+(would not be unique)$/', $msg)) { $e = new \Exception('Такая запись уже существует.', $c, $e); } if (preg_match('/.+(Primary key for row in table).+(is referenced by foreign key).+(in table).+/', $msg)) { $e = new \Exception('Нельзя удалить запись, так как она связана с другими данными.', $c, $e); } if (isset($e->errorCodeStr)) { error_log($msg); $e = new \Exception($msg.' (код ошибки: '.$e->errorCodeStr.')', $c, $e); } } else { switch ($c) { case 23503: $e = new \Exception(safe_strpos($msg, 'insert or update') === false ? 'Нельзя удалить запись, так как она связана с другими данными.' : 'Нарушение ограничения вторичного ключа при вставке или обновлении записи.', $c, $e); break; case 23505: $e = new \Exception('Такая запись уже существует.', $c, $e); break; case 22003: $e = new \Exception('Превышено максимальное количество символов в полях.', $c, $e); break; default: $m = _parseExceptionMessage($msg); if (!empty($m)) { $e = new \Exception("[$c] $m", -1, $e); } break; } } } return $e; } function exceptionToJsonRpcError ($e) { global $jsonRpcExceptionNoDebug; $error = new \stdClass; $error->code = $e->getCode(); $error->message = $e->getMessage(); if (!$jsonRpcExceptionNoDebug) { $error->debug = $debug = new \stdClass; $debug->file = $e->getFile().'('.$e->getLine().')'; $debug->line = $e->getLine(); $debug->trace = $e->getTraceAsString(); $previous = $e->getPrevious(); if ($previous) { $debug->previous = exceptionToJsonRpcError($previous); } } return $error; } function exceptionToJsonRpcResponse ($e) { $response = new \stdClass; $response->jsonrpc = '2.0'; $response->id = isset($e->id)? $e->id : null; if ($e->getCode() === E_FATAL_ERROR) { $response->fatalError = true; } $response->error = exceptionToJsonRpcError($e); return json_encode($response, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES); } set_exception_handler(function($e) { $res = exceptionToJsonRpcResponse(decorateException($e)); error_log('EXCEPTION to JSON response: ' . $res); echo $res; }); function app_log ($message, $type = 0, $name = '', $e = null) { static $time = null; if ($type == 3) { $t = microtime(true); $s = round($t - $time, 3); $log = " $message ({$s}s)"; $time = $t; } else { $type = $type == 0 ? "INFO" : ($type == 1 ? "WARNING" : "ERROR"); $date = date("d.m.Y H:i:s"); $log = "\n$date $type\t$message"; $time = microtime(true); } $name = ($name ?: getSessionValue("app")) ?: 'no_select_app'; error_log($log, 3, getLogPath() . $name . '.log'); if ($e) { if ($message == $e->getMessage()) { throw $e; } else { throw new Exception($message, 0, $e); } } } function _parseExceptionMessage ($msg) { $matches = []; $res = mb_eregi('ERROR:(.*)(DETAIL:|CONTEXT:)', $msg, $matches); if (empty($res)) { $res = mb_eregi('ERROR:(.*)', $msg, $matches); } if (!empty($matches[1])) { error_log('PDO ERROR: ' . print_r($matches[1], true)); return trim($matches[1]); } } function throwJsonRpc($throwable, $http_response_code = 500) { global $jsonRpcExceptionNoDebug; http_response_code($http_response_code); $jsonRpcExceptionNoDebug = true; throw $throwable; }